import numpy as np

def analyze(c, dims, req, target=4):
    gap = sum(max(0, target - c[dims.index(k)]) * w for k, w in req.items())
    gains = []
    for k, w in req.items():
        i = dims.index(k)
        if c[i] < target:
            gains.append((w, k, c[i]))          # 每 +1 分固定减少 w
    j = np.zeros(len(dims))
    for k, w in req.items():
        j[dims.index(k)] = w
    cos = c @ j / (np.linalg.norm(c) * np.linalg.norm(j) + 1e-12)
    return gap, sorted(gains, reverse=True), cos

from collections import defaultdict, deque

def schedule(tasks):
    dur = {t: d for t, d, _ in tasks}
    pre = {t: p for t, _, p in tasks}
    succ, indeg = defaultdict(list), {t: len(p) for t, _, p in tasks}
    for t, _, ps in tasks:
        for x in ps: succ[x].append(t)
    q = deque(t for t in indeg if indeg[t] == 0); order = []
    while q:
        u = q.popleft(); order.append(u)
        for v in succ[u]:
            indeg[v] -= 1
            if indeg[v] == 0: q.append(v)
    assert len(order) == len(tasks)
    ES = {t: max((ES[p] + dur[p] for p in pre[t]), default=0) for t in order}
    total = max(ES[t] + dur[t] for t in tasks)
    LF = {t: total for t, _, _ in tasks}
    for t in reversed(order):
        if succ[t]: LF[t] = min(LF[s] - dur[s] for s in succ[t])
    return order, ES, LF, total
